    80→  @Override
    81→  public boolean verifyBlobKzgProof(
    82→      final Bytes blob, final KZGCommitment kzgCommitment, final KZGProof kzgProof)
    83→      throws KZGException {
    84→    try {
    85→      return library.verifyBlobKzgProof(
    86→          blob.toArrayUnsafe(), kzgCommitment.toArrayUnsafe(), kzgProof.toArrayUnsafe());
    87→    } catch (final Exception ex) {
    88→      throw new KZGException(
    89→          "Failed to verify blob and commitment against KZG proof " + kzgProof, ex);
    90→    }
    91→  }
    92→
    93→  @Override
    94→  public boolean verifyBlobKzgProofBatch(
    95→      final List<Bytes> blobs,
    96→      final List<KZGCommitment> kzgCommitments,
    97→      final List<KZGProof> kzgProofs)
    98→      throws KZGException {
    99→    try {
   100→      if (blobs.size() != kzgCommitments.size() || kzgProofs.size() != kzgCommitments.size()) {
   101→        throw new IllegalArgumentException(
   102→            String.format(
   103→                "Number of blobs(%d), commitments(%d) and proofs(%d) do not match",
   104→                blobs.size(), kzgCommitments.size(), kzgProofs.size()));
   105→      }
   106→      final byte[][] blobsBytes = new byte[blobs.size()][];
   107→      final byte[][] commitmentsBytes = new byte[kzgCommitments.size()][];
   108→      final byte[][] proofsBytes = new byte[kzgProofs.size()][];
   109→      for (int i = 0; i < blobs.size(); i++) {
   110→        blobsBytes[i] = blobs.get(i).toArrayUnsafe();
   111→        commitmentsBytes[i] = kzgCommitments.get(i).toArrayUnsafe();
   112→        proofsBytes[i] = kzgProofs.get(i).toArrayUnsafe();
   113→      }
   114→      return library.verifyBlobKzgProofBatch(blobsBytes, commitmentsBytes, proofsBytes);
   115→    } catch (final Exception ex) {
   116→      throw new KZGException(
   117→          "Failed to verify blobs and commitments against KZG proofs " + kzgProofs, ex);
   118→    }
   119→  }
   120→
   121→  @Override
   122→  public KZGCommitment blobToKzgCommitment(final Bytes blob) throws KZGException {
   123→    try {
   124→      final byte[] commitmentBytes = library.blobToKZGCommitment(blob.toArrayUnsafe());
   125→      return KZGCommitment.fromArray(commitmentBytes);
   126→    } catch (final Exception ex) {
   127→      throw new KZGException("Failed to produce KZG commitment from blob", ex);
   128→    }
   129→  }
   130→
   131→  @Override
   132→  public KZGProof computeBlobKzgProof(final Bytes blob, final KZGCommitment kzgCommitment)
   133→      throws KZGException {
   134→    try {
   135→      final byte[] proof =
   136→          library.computeBlobKzgProof(blob.toArrayUnsafe(), kzgCommitment.toArrayUnsafe());
   137→      return KZGProof.fromArray(proof);
   138→    } catch (final Exception ex) {
   139→      throw new KZGException(
   140→          "Failed to compute KZG proof for blob with commitment " + kzgCommitment, ex);
   141→    }
   142→  }
   143→
   144→  @Override
   145→  public List<KZGCell> computeCells(final Bytes blob) {
   146→    final Cells cells = library.computeCells(blob.toArrayUnsafe());
   147→    return KZGCell.splitBytes(Bytes.wrap(cells.toBytes()));
   148→  }
   149→
   150→  @Override
   151→  public List<KZGCellAndProof> computeCellsAndProofs(final Bytes blob) {
   152→    final CellsAndProofs cellsAndProofs = library.computeCellsAndKZGProofs(blob.toArrayUnsafe());
   153→    final Stream<KZGCell> kzgCellStream =
   154→        Arrays.stream(cellsAndProofs.getCells()).map(Bytes::wrap).map(KZGCell::new);
   155→
   156→    final Stream<KZGProof> kzgProofStream =
   157→        Arrays.stream(cellsAndProofs.getProofs()).map(Bytes48::wrap).map(KZGProof::new);
   158→
   159→    return Streams.zip(kzgCellStream, kzgProofStream, KZGCellAndProof::new).toList();
   160→  }
   161→
   162→  @Override
   163→  public boolean verifyCellProofBatch(
   164→      final List<KZGCommitment> commitments,
   165→      final List<KZGCellWithColumnId> cellWithIdList,
   166→      final List<KZGProof> proofs) {
   167→    return library.verifyCellKZGProofBatch(
   168→        commitments.stream().map(KZGCommitment::toArrayUnsafe).toArray(byte[][]::new),
   169→        cellWithIdList.stream()
   170→            .mapToLong(cellWithIds -> cellWithIds.columnId().id().longValue())
   171→            .toArray(),
   172→        cellWithIdList.stream()
   173→            .map(cellWithIds -> cellWithIds.cell().bytes().toArrayUnsafe())
   174→            .toArray(byte[][]::new),
   175→        proofs.stream().map(KZGProof::toArrayUnsafe).toArray(byte[][]::new));
   176→  }
   177→
   178→  @Override
   179→  public List<KZGCellAndProof> recoverCellsAndProofs(final List<KZGCellWithColumnId> cells) {
   180→    final long[] cellIds = cells.stream().mapToLong(c -> c.columnId().id().longValue()).toArray();
   181→    final byte[][] cellBytes =
   182→        cells.stream().map(c -> c.cell().bytes().toArrayUnsafe()).toArray(byte[][]::new);
   183→    final CellsAndProofs cellsAndProofs = library.recoverCellsAndKZGProofs(cellIds, cellBytes);
   184→    final byte[][] recoveredCells = cellsAndProofs.getCells();
   185→    final Stream<KZGCell> kzgCellStream =
   186→        Arrays.stream(recoveredCells).map(Bytes::wrap).map(KZGCell::new);
   187→    final byte[][] recoveredProofs = cellsAndProofs.getProofs();
   188→    final Stream<KZGProof> kzgProofStream =
   189→        Arrays.stream(recoveredProofs).map(Bytes48::wrap).map(KZGProof::new);
   190→    return Streams.zip(kzgCellStream, kzgProofStream, KZGCellAndProof::new).toList();
   191→  }
   192→}
